const LEAF_POLICY: &str = "limbo (RFC 5280 only) accepts a CA certificate in leaf position; check_leaf_certificate rejects it as an end entity (BasicConstraints cA, and KeyUsage without digitalSignature), a stricter WebPKI-style policy, not a decoder bug";
const NO_PEER_NAME: &str = "SUCCESS without a DNS or IP peer name, so no RFC 9525 check applies; needs path validation (3.5b)";

